using System.Text.Json;
// No UIA or process calls. Fixed tokens and bounded numeric data only.
sealed record DiagnosticEntry(long Sequence,double Seconds,string Checkpoint,string Operation,string Id,string Field,string Result,string Status,string Expected,string Observed,int? Session,int? Handle);
sealed class DiagnosticJournal {
 readonly object gate=new();readonly Queue<DiagnosticEntry> entries=new();long sequence;string checkpoint="START";DiagnosticEntry? active,terminal,lastRead;
 static readonly HashSet<string> ids=new(new[]{"owned-main","owned-sentinel","owned-value","owned-toggle","owned-text"},StringComparer.Ordinal);
 static readonly HashSet<string> tokens=new(new[]{"IDENTITY_SUPPRESSED","SUPPRESSED","FIRST_DESKTOP","NEXT_DESKTOP","FIRST_CONTROL","NEXT_CONTROL","PID_WITNESS","SESSION_DISPOSE","NODE","END","JSON_PARSE","OBSERVER_REPORT_CAP","ACQUISITION_ID_REUSE","AFTER_CLOSE_SURVIVING_ROOTS","AFTER_FIXTURE_CLOSE","ASSERTION","ASSERTION_FAILED","AcquisitionFailed","AutomationId","BASELINE","BASELINE_OWNED_ROOT_COUNT","BASELINE_RAW_OWNED_SET_DIFFERENCE","BASELINE_RESULT_CAP","BEGIN","Binding","BindingMismatch","CACHE_SILENT_CURRENT_FALLBACK","CANONICAL_","CANONICAL_DIGEST_BINDING","CANONICAL_DIGEST_RELEASE","CANONICAL_NON_SUPPORT_UNRELATED_FAILURE","CANONICAL_OffPrecheck","CANONICAL_PreConnect","CANONICAL_REFUSAL","CANONICAL_SCOPE","COMMAND_","COMMAND_CLOSE","COMMAND_MIXED","COMMAND_ON","COMMAND_STOP","Cancelled","CanonicalShape","CheckBox","ClassName","ClockReversed","Control","ControlDescendants","ControlType","ControlTypeId","DEFAULT_FALLBACK","DESKTOP_COMPARISON","DISPOSED","DUPLICATE_SYNTHETIC_ID","DepthCap","DesktopBudget","DesktopRoots","DirectDesktopChildren","DisposalFailed","Disposed","Document","ELEMENT_NOT_AVAILABLE","ELEMENT_NOT_AVAILABLE_EXCEPTION","EXCEPTION","Edit","Element","Enabled","ExactCount","FACT_CAP","FALSE","FIELD_READ","FINAL_COUNTS","FINAL_SESSION_CALL_COUNTS","FINAL_STOP","FIXTURE_ACK_TIMEOUT","FIXTURE_IDS_MISSING","FOREIGN_HANDLE_NEGATIVE","FOREIGN_HANDLE_NOT_REJECTED_LOCALLY","FOREIGN_HANDLE_PROBE","FRESH_ACQUISITION_ID","FRESH_AFTER_CLOSE_ACQUISITION_REFUSED","FRESH_TOPOLOGY_REFUSAL","FROZEN_CACHE","FROZEN_VALUE","Failed","Full","Hwnd","IDS_AFTER_CLOSE","IDS_INITIAL","ID_WITHOUT_OWNED_PID","INDETERMINATE_REFRESH","INITIAL_ACQUISITION_REFUSED","INITIAL_KNOWN_IDS","INITIAL_OFF","INITIAL_VALUE","INVALID_OPERATION","INVALID_STAGE","IO_EXCEPTION","IPC_ACK","IPC_COMMAND","IPC_STOP","Indeterminate","Inspect","InspectDiscovery","InvalidType","KNOWN_IDS_AFTER_CLOSE","LIFETIME","LOCAL_REJECTION","MembershipUnavailable","NA","NAVIGATION_PREFETCH","NEW_ACQUISITION_STALE_MAIN_CONTROLS","NONZERO","NON_PRESENT","NOT_READ","NOT_RETURNED","Name","NodeCap","NonJobDescendant","NotRequested","NullField","NullSession","OBSERVER","OBSERVER_BUDGET","OBSERVER_JOIN","OBSERVER_START","OLD_HANDLE_ACCEPTED_BY_NEW_SESSION","OLD_HANDLE_NEGATIVE","OLD_HANDLE_PROBE","OMITTED_CACHE_CURRENT_FALLBACK","OMITTED_CACHE_PROPERTY","OMITTED_NAME","OTHER","OTHER_EXCEPTION","OTHER_NUMBER","OTHER_STRING","OWNED_TOPOLOGY_CHECKS_COMPLETED_CANONICAL_REPORTED_SEPARATELY","Off","OffPrecheck","Offscreen","On","Opening","Other","PARSED","PRESENT","PROBE_CALL_DELTA","PROVIDER_STALE_PRESENT_AFTER_CLOSE","Pane","PatternMismatch","PostOff","PostOn","PreConnect","PreOn","Present","ProcessId","ProgrammaticName","PromptCandidates","ProviderPid","Publication","RAW_COMPARISON","RAW_RESULT_CAP","REFRESH_AFTER_OWNED_UPDATE","REFRESH_LOGICAL_IDENTITY_CHANGED","REFRESH_RUNTIME_ID_CHANGED","RELEASE_INVALIDATION","RELEASE_NEGATIVE","RELEASE_PROBE","REQUIRED_SYNTHETIC_FIELD_UNAVAILABLE","REQUIRE_PRESENT","RETURN","ROOTS_AFTER_CLOSE","Raw","RawDesktopChildren","Reentrant","RequiredUnavailable","ReusedSession","RootCap","RuntimeId","STAGED_READS_AND_REFRESH","STAGE_","STAGE_0","STAGE_1","STAGE_2","STAGE_3","STAGE_POLICY","STAGE_READSET","STALE_AFTER_CLOSE","STALE_READ_UNCLASSIFIED_EXCEPTION","START","STATIC_TEXT_FAKE_DEFAULT","STATIC_TEXT_VALUE_AVAILABILITY","STATIC_TEXT_VALUE_STATUS","STOP","SUPPLEMENTAL_READ","Setup","Shape","ShapeIncomplete","ShapeProcessId","SiblingCap","SourceFailed","TEXT_AVAILABILITY","TEXT_VALUE_NEGATIVE","THREAD_TIMEOUT","TIMEOUT","TOGGLE_","TOGGLE_0","TOGGLE_1","TOGGLE_2","TOGGLE_AVAILABLE","TOGGLE_INITIAL","TOGGLE_MIXED_REFRESH","TOGGLE_ON_REFRESH","TOGGLE_PATTERN","TOPOLOGY_AFTER_CLOSE","TOPOLOGY_DIGEST_NEGATIVE","TOPOLOGY_INITIAL","TOPOLOGY_OWNED_HANDLE_COUNT","TOPOLOGY_REFUSAL","TOPOLOGY_SCOPE","TOPOLOGY_TICKET_MINTED_CANONICAL_DIGEST","TRANSPORT_CALL_CAP","TRUE","TYPE_","TYPE_50000","TYPE_50001","TYPE_50002","TYPE_50003","TYPE_50004","TYPE_50005","TYPE_50006","TYPE_50007","TYPE_50008","TYPE_50009","TYPE_50010","TYPE_50011","TYPE_50012","TYPE_50013","TYPE_50014","TYPE_50015","TYPE_50016","TYPE_50017","TYPE_50018","TYPE_50019","TYPE_50020","TYPE_50021","TYPE_50022","TYPE_50023","TYPE_50024","TYPE_50025","TYPE_50026","TYPE_50027","TYPE_50028","TYPE_50029","TYPE_50030","TYPE_50031","TYPE_50032","TYPE_50033","TYPE_50034","TYPE_50035","TYPE_50036","TYPE_50037","TYPE_50038","TYPE_50039","TYPE_50040","TYPE_50041","TYPE_50042","TYPE_50043","TYPE_50044","TYPE_50045","TYPE_50046","TYPE_50047","TYPE_50048","TYPE_50049","TYPE_50050","Text","Toggle","ToggleAvailable","TogglePatternType","ToggleState","TopologyOnly","Traversal","UNAVAILABLE","UNCLASSIFIED_EXCEPTION","UNEXPECTED_OBSERVER_EXCEPTION","UNKNOWN","UnknownPid","Unsupported","VALUE_A","VALUE_AVAILABLE","VALUE_B","VALUE_CACHE_NOT_CAPTURED","VALUE_INITIAL","VALUE_PATTERN","VALUE_PATTERN_TYPE","VALUE_PATTERN_UNAVAILABLE","VALUE_REFRESH","Value","ValueAvailable","ValuePatternType","WRITTEN","WRONG_THREAD_NEGATIVE","WRONG_THREAD_NOT_REJECTED_LOCALLY","WRONG_THREAD_PROBE","Window","WrongPhase","WrongPlan","WrongThread","WrongType","ZERO","close","mixed","on","owned-main","owned-sentinel","owned-text","owned-toggle","owned-value","owned-value-A","owned-value-B","step","stop"},StringComparer.Ordinal);
 static string Token(string? s)=>s is not null&&tokens.Contains(s)?s:"UNKNOWN";
 public static string Id(string? s)=>s is not null&&ids.Contains(s)?s:"UNKNOWN";
 public static string ExceptionToken(Exception e)=>e is ObjectDisposedException?"DISPOSED":e is InvalidOperationException?"INVALID_OPERATION":e is IOException?"IO_EXCEPTION":e is TimeoutException?"TIMEOUT":"OTHER_EXCEPTION";
 public void Checkpoint(string value){lock(gate){checkpoint=Token(value);active=null;lastRead=null;}}
 public void Record(double seconds,string operation,string id,string field,string result,string status,string expected="NA",string observed="NA",int? session=null,int? handle=null){lock(gate){var e=new DiagnosticEntry(++sequence,seconds,checkpoint,Token(operation),Id(id),Token(field),Token(result),Token(status),Token(expected),Token(observed),session,handle);if(entries.Count==16)entries.Dequeue();entries.Enqueue(e);if(result=="BEGIN")active=e;if(operation=="FIELD_READ"&&result is "RETURN" or "EXCEPTION")lastRead=e;if(result is "EXCEPTION" or "ASSERTION_FAILED")terminal=e;}}
 public object Snapshot(){lock(gate)return new{checkpoint,precedingFieldRead=lastRead,precedingReadIsNotCauseProof=true,capacity=16,total=sequence,dropped=Math.Max(0,sequence-16),lastStartedOperation=active,lastExceptionOrAssertion=terminal,entries=entries.ToArray()};}
}

sealed class DiagnosticContext(DiagnosticJournal journal,Func<double> clock) { public string? LastLocalRefusal{get;private set;} public void Fail(string code){LastLocalRefusal=code;journal.Record(clock(),"ASSERTION","UNKNOWN","NA","ASSERTION_FAILED","NA",code);} }
